excels.excel:

EXPORT WITH SHEET="应收账款账龄台账", HEADER=true,
    MAPPING={"a":"客户名称","b":"应收金额","c":"已收金额","d":"未收余额","e":"账龄(天)","f":"未收占比"},
    FORMAT={"b":"#,##0.00","c":"#,##0.00","d":"#,##0.00","e":"0","f":"0.00%"},
    FORMULAS={
        D2:'B2-C2',D3:'B3-C3',D4:'B4-C4',D5:'B5-C5',D6:'B6-C6',
        F2:'D2/D7',F3:'D3/D7',F4:'D4/D7',F5:'D5/D7',F6:'D6/D7',
        B7:'SUM(B2:B6)',C7:'SUM(C2:C6)',D7:'SUM(D2:D6)',F7:'SUM(F2:F6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        D6:{color:red,bold:true},
        E6:{color:red,bold:true}
    }
